import { MakeLogicType, actions, afterMount, kea, listeners, path, reducers } from 'kea'

import { type Preference, apply, read, write } from '@hanzo/appearance/state'

/** The steps offered for text size, inside the range @hanzo/design clamps to. */
export const TYPE_STEPS = [0.85, 1, 1.15, 1.3] as const

export type Density = NonNullable<Preference['density']>

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface appearanceLogicValues {
    preference: Preference
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface appearanceLogicActions {
    loadStored: () => {
        value: true
    }
    setDensity: (density: Density) => {
        density: Density
    }
    setType: (type: number) => {
        type: number
    }
}

export type appearanceLogicType = MakeLogicType<appearanceLogicValues, appearanceLogicActions>

export const appearanceLogic = kea<appearanceLogicType>([
    path(['scenes', 'settings', 'user', 'appearanceLogic']),
    actions({
        setType: (type: number) => ({ type }),
        setDensity: (density: Density) => ({ density }),
        loadStored: true,
    }),
    reducers({
        preference: [
            {} as Preference,
            {
                setType: (state, { type }) => ({ ...state, type }),
                setDensity: (state, { density }) => ({ ...state, density }),
                loadStored: () => read(),
            },
        ],
    }),
    listeners(({ values }) => {
        // The document is the only place a preference is visible, and storage is the
        // only place it survives a reload, so both happen on every change rather than
        // one of them waiting for a save.
        const persist = (): void => {
            write(values.preference)
            apply(values.preference)
        }
        return { setType: persist, setDensity: persist }
    }),
    afterMount(({ actions }) => {
        // The entry already applied the stored preference before first paint. This
        // reads it back so the controls open on what is actually in effect, including
        // a change made in another tab since this one loaded.
        actions.loadStored()
    }),
])
